add_action( 'woocommerce_after_checkout_validation', 'perfectpixel_no_po_box_shipping', 10, 2 );

function perfectpixel_no_po_box_shipping( $data, $errors ) {
	if ( ! WC()->cart || ! WC()->cart->needs_shipping() ) {
		return;
	}
	$prefix  = ! empty( $data['ship_to_different_address'] ) ? 'shipping_' : 'billing_';
	$address = ( $data[ $prefix . 'address_1' ] ?? '' ) . ' ' . ( $data[ $prefix . 'address_2' ] ?? '' );

	$pattern = '/\b(p\.?\s*o\.?\s*box|post\s+office\s+box)\b|(^|[\s,])(τ\.?\s*θ\.?|ταχ(υδρομική|\.)?\s*θυρίδα)([\s,.\d]|$)/iu';
	if ( preg_match( $pattern, $address ) ) {
		$errors->add( 'perfectpixel_po_box', esc_html( '{{po_box_message}}' ) );
	}
}
